import React from 'react';
import {Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend);

// Fake data for visualization - connect to backend /metrics later if needed
const latencyData = {
  labels: ['1MB', '5MB', '10MB', '50MB', '100MB'],
  datasets: [
    {
      label: 'Hybrid PQC (Kyber+AES)',
      data: [120, 450, 890, 4200, 8500],
      borderColor: '#00ff9d',
      backgroundColor: 'rgba(0, 255, 157, 0.5)',
    },
    {
      label: 'Baseline (RSA+AES)',
      data: [300, 800, 1500, 6000, 12000],
      borderColor: '#ff0055',
      backgroundColor: 'rgba(255, 0, 85, 0.5)',
    },
  ],
};

const Performance = () => {
  return (
    <div className="p-8 space-y-8 h-full overflow-y-auto">
       <h2 className="text-2xl font-bold text-white mb-2">Performance Metrics</h2>
       
       <div className="grid grid-cols-2 gap-8">
           {/* Chart 1: Latency */}
           <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
               <h3 className="text-gray-400 text-sm mb-4">Encryption Latency (ms)</h3>
               <Line options={{ responsive: true, plugins: { legend: { position: 'bottom' } } }} data={latencyData} />
           </div>

           {/* Metrics Cards */}
           <div className="grid grid-cols-2 gap-4">
               <MetricCard title="Avg. PQC Encap Time" value="0.04 ms" sub="Kyber-512" />
               <MetricCard title="Avg. AES Throughput" value="2.4 GB/s" sub="AES-NI Enabled" />
               <MetricCard title="Handshake Overhead" value="1.5 KB" sub="Quantum Keys" />
               <MetricCard title="Integrity Check" value="SHA-256" sub="HMAC/GCM" />
           </div>
       </div>
    </div>
  );
};

const MetricCard = ({ title, value, sub }) => (
    <div className="bg-black/40 border border-gray-800 p-6 rounded-lg flex flex-col justify-center items-center text-center">
        <p className="text-gray-500 text-xs uppercase mb-2">{title}</p>
        <p className="text-3xl font-bold text-neon-green font-mono">{value}</p>
        <p className="text-gray-600 text-[10px] mt-1">{sub}</p>
    </div>
);

export default Performance;
